import {tr,localize,messageError} from './i18n.mjs';
import {parseSms,localDate,fingerprint} from './domain.mjs';
import {filterPayments,paymentAnalysis,simulationMessage,timeParts,precisionLabel,transferFacts,smsTiming,isIncoming,paymentZone} from './payments.mjs';
export function paymentPreview(t,escape){
  if(!t.incomingTransfer)return '';
  const stamp=i=>{const p=timeParts(i,t.timeZone);return p?`${p.date} ${p.time} · ${tr(precisionLabel(i))}`:tr('Not provided');};
  return `<div class="incoming-import-note"><strong>${escape(tr('Incoming payment · {payer}',{payer:t.payer||tr('Payer not identified')}))}</strong><p>${escape(tr('Bank time: {time}',{time:stamp(t.transactionTime)}))}</p><p>${escape(tr('SMS arrival: {time}',{time:stamp(t.receivedTime)}))}</p><p>${escape(t.timeZone)} · ${escape(tr(t.paymentChannel))} · ${escape(tr('Reference {reference}',{reference:t.reference||tr('not supplied')}))}</p></div>`;
}

export function initPayments({getState,changed,escape,money,icon,toast,setView}) {
  const $=id=>document.getElementById(id);
  for(const t of getState().transactions){
    if(t.source==='sms'&&t.incomingTransfer===undefined){const facts=transferFacts(t.raw,t.type);Object.assign(t,facts,smsTiming({},t.raw,t.currency,t.date));t.incomingTransfer=t.type==='income';}
  }
  const nav=document.createElement('button');nav.dataset.view='incoming';nav.className='nav-item';nav.setAttribute('aria-label','Incoming payments');nav.title='Incoming payments';nav.innerHTML=icon('arrow-down-left')+'<span>Incoming payments</span>';nav.onclick=()=>setView('incoming');
  document.querySelector('nav').insertBefore(nav,document.querySelector('[data-view="rules"]'));localize(nav);
  const host=document.createElement('section');host.id='incoming-view';host.className='hidden';
  host.innerHTML=`
    <div class="payment-banner"><div><strong id="payment-mode-title">Simulation inbox</strong><p id="payment-mode-description">Practice with fictional payments. Your saved money records stay separate.</p></div><div class="payment-mode" role="group" aria-label="Payment dataset"><button id="payment-demo-mode" aria-pressed="true">Simulation</button><button id="payment-real-mode" aria-pressed="false">My messages</button></div></div>
    <div class="payment-toolbar"><button id="simulate-payment" class="button primary">${icon('plus')} Simulate incoming SMS</button><button id="payment-reset-demo" class="button secondary">Load sample day</button><button id="payment-import" class="button secondary">Import bank messages</button></div>
    <form id="payment-filters" class="panel payment-filters" aria-label="Incoming payment filters">
      <label>Currency<select id="payment-currency"><option value="VND">₫ VND</option><option value="KRW">₩ KRW</option></select></label>
      <label>Bank<select id="payment-bank"><option value="all">All banks</option></select></label>
      <label>Month<input id="payment-month" type="month"></label>
      <label>Specific day<input id="payment-day" type="date"></label>
      <details class="payment-advanced" ${window.matchMedia('(min-width:701px)').matches?'open':''}><summary>Time, channel & search filters</summary><div class="payment-advanced-fields">
      <label>Time zone<select id="payment-zone"><option value="Asia/Ho_Chi_Minh">Vietnam · UTC+07</option><option value="Asia/Seoul">Korea · UTC+09</option></select></label>
      <label>Analyze using<select id="payment-basis"><option value="transaction">Bank transaction time</option><option value="received">SMS arrival time</option></select></label>
      <label>Part of day<select id="payment-period"><option value="all">All times</option><option>Night</option><option>Morning</option><option>Afternoon</option><option>Evening</option><option>Unknown</option></select></label>
      <label>Channel<select id="payment-channel"><option value="all">All channels</option><option>Facebook</option><option>Direct transfer</option><option>Unclassified</option></select></label>
      <label>From time<input id="payment-from" type="time" step="0.001"></label>
      <label>To time<input id="payment-to" type="time" step="0.001"></label>
      <label>Order<select id="payment-sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label>
      <label>Find a payment<input id="payment-query" type="search" placeholder="Payer, reference, memo…"></label>
      </div></details>
      <button id="payment-clear-filters" type="button" class="text-button">Reset filters</button>
    </form>
    <div class="payment-stats" aria-label="Incoming payment summary"><article class="stat-card featured"><div class="stat-title">Money received</div><h2 id="payment-total">₫0</h2><p id="payment-count" class="stat-detail">0 payments</p></article><article class="stat-card"><div class="stat-title">Busiest hour</div><h2 id="payment-peak">—</h2><p id="payment-peak-note" class="stat-detail">No timed payments</p></article><article class="stat-card"><div class="stat-title">Millisecond timestamps</div><h2 id="payment-precise">0</h2><p id="payment-unknown" class="stat-detail">0 without time</p></article></div>
    <section class="panel payment-chart-panel"><div class="panel-heading"><div><h2>When money arrives</h2><p id="payment-chart-description">Payments by hour of day</p></div><span class="muted">Payment count</span></div><div id="payment-hours" class="payment-hours"></div><div id="payment-periods" class="payment-periods"></div></section>
    <section class="panel payment-ledger"><div class="panel-heading"><div><h2>Incoming payment messages</h2><p id="payment-ledger-description">Select a payment to see both timestamps and the original SMS.</p></div><button id="payment-export" class="button secondary">Export list</button></div><div class="table-scroll"><table><thead><tr><th>Payer & message</th><th>Time · selected zone</th><th>Account</th><th>Channel</th><th class="align-right">Received</th><th><span class="sr-only">Details</span></th></tr></thead><tbody id="payment-rows"></tbody></table></div><div id="payment-empty" class="empty hidden"><h3>No matching incoming payments</h3><p>Try the simulator, import credited bank messages, or clear your filters.</p></div><p class="payment-time-note">Bank time and SMS arrival time can differ. Unknown milliseconds are never filled in. Minute- or second-only timestamps overlap a matching time range; order within that interval is unknown.</p></section>`;
  document.querySelector('.main-footer').before(host);localize(host);
  host.insertBefore(host.querySelector('.payment-stats'),host.querySelector('.payment-filters'));
  const sim=document.createElement('dialog');sim.id='payment-sim-dialog';sim.setAttribute('aria-labelledby','payment-sim-title');
  sim.innerHTML=`<div class="dialog-heading"><div><p class="eyebrow">FICTIONAL PAYMENTS ONLY</p><h2 id="payment-sim-title">Someone sends you money</h2></div><button class="icon-button" id="payment-sim-close" aria-label="Close payment simulator">×</button></div><p>Generate a bank notification for an incoming transfer. This does not send money or contact a bank.</p><form id="payment-sim-form"><div class="form-grid"><label>Bank / currency<select id="sim-currency"><option value="VND">Vietcombank · VND</option><option value="KRW">Shinhan · KRW</option></select></label><label>Sender's name<input id="sim-payer" required maxlength="100" value="Nguyen Minh Anh"></label><label>Amount received<input id="sim-amount" type="number" min="1" max="1000000000000" step="1" value="250000" required></label><label>Date<input id="sim-date" type="date" required></label><label>Bank time (milliseconds)<input id="sim-time" type="time" step="0.001" value="14:32:18.123" required></label><label>SMS delay in milliseconds<input id="sim-delay" type="number" min="0" max="600000" step="1" value="850" required></label><label>Payment reference<input id="sim-reference" required maxlength="60"></label><label>Payment memo<input id="sim-memo" maxlength="150" value="Facebook order FB-1042"></label></div><p id="sim-zone-note" class="helper">Bank clock uses Vietnam time (UTC+07).</p><button id="sim-preview" type="button" class="text-button">Preview message</button><pre id="sim-sms-preview" class="raw-message"></pre><p id="sim-error" class="error" role="alert"></p><div class="dialog-actions"><button class="button primary" type="submit">Deliver simulated SMS</button></div></form>`;
  document.body.append(sim);localize(sim);
  const detail=document.createElement('dialog');detail.id='payment-detail-dialog';detail.setAttribute('aria-labelledby','payment-detail-title');
  detail.innerHTML=`<div class="dialog-heading"><h2 id="payment-detail-title">Payment details</h2><button class="icon-button" id="payment-detail-close" aria-label="Close payment details">×</button></div><div id="payment-detail-summary"></div><form id="payment-detail-form"><input id="payment-detail-id" type="hidden"><div class="form-grid"><label>Payer<input id="payment-detail-payer" maxlength="100"></label><label>Channel<select id="payment-detail-channel"><option>Unclassified</option><option>Facebook</option><option>Direct transfer</option></select></label><label>Account<input id="payment-detail-account" maxlength="30"></label><label>Payment kind<select id="payment-detail-kind"><option value="external">Received from another person</option><option value="own">Between my own accounts (exclude)</option></select></label></div><label>Memo<input id="payment-detail-memo" maxlength="300"></label><p class="helper">A Facebook label comes from the message text or your choice. It does not verify a Facebook order.</p><details open><summary>Original bank SMS</summary><pre id="payment-detail-raw" class="raw-message"></pre></details><div class="dialog-actions"><button class="button primary" type="submit">Save classification</button></div></form>`;
  document.body.append(detail);localize(detail);

  let mode=getState().transactions.some(isIncoming)&&!getState().demo?'real':'simulation';
  let demo=[],rows=[],counter=0;
  let currency=getState().currency==='KRW'?'KRW':'VND';
  const filters={currency,bank:'all',month:localDate().slice(0,7),day:'',period:'all',channel:'all',query:'',zone:paymentZone(currency),basis:'transaction',from:'',to:'',sort:'newest'};
  function demoDay(){
    const date=localDate();const entries=[['00:03:05.020','Le Thu Ha',120000,'Direct transfer'],['07:45:10','Tran Hoang',180000,'Facebook bag FB-1001'],['09:05','Nguyen Mai',65000,'Facebook book FB-1002'],['12:15:33.402','Pham Linh',320000,'Facebook shoes FB-1003'],['14:32:18.123','Nguyen Minh Anh',250000,'Facebook order FB-1042'],['14:32:18.987','Do Anh Tuan',250000,'Facebook order FB-1043'],['18:20:02.056','Bui Lan',450000,'Facebook camera FB-1044'],['21:08:55.701','Vu Minh',90000,'Direct transfer']];
    demo=[];
    for(const cur of ['VND','KRW'])for(const [time,payer,amount,memo] of entries){const id=`SIM-${cur}-${++counter}`;const message=simulationMessage({payer:cur==='KRW'?['김민수','이지은','박서준'][counter%3]:payer,amount:cur==='KRW'?Math.round(amount/10):amount,currency:cur,date,time,reference:id,memo,delayMs:counter%3===0?1450:850});const result=parseSms(message,{currency:cur,date});if(result.status==='parsed')demo.push({...result.transaction,id,simulation:true});}
    // A real-world precision gap: a date-only credit cannot be assigned an hour.
    for(const cur of ['VND','KRW']){const id=`SIM-${cur}-${++counter}`;const message=cur==='VND'?`VCB: GD +75000 VND ngay ${date}. Nguoi gui: Nguyen An; ND: Facebook order date only; Ref: ${id}.`:`[신한은행] 입금 7,500원 ${date}\n입금자: 정유진\n메모: Facebook order date only\n거래번호: ${id}`;const r=parseSms(message,{currency:cur,date});if(r.status==='parsed')demo.push({...r.transaction,id,simulation:true});}
  }
  demoDay();
  function data(){return mode==='simulation'?demo:getState().demo?[]:getState().transactions;}
  function writeFilters(){for(const key of Object.keys(filters))$(`payment-${key}`)?.setAttribute('data-filter',key);for(const key of Object.keys(filters)){const el=$(`payment-${key}`);if(el)el.value=filters[key];}}
  function render(){
    host.classList.toggle('hidden',getState().view!=='incoming');if(getState().view!=='incoming')return;
    $('payment-demo-mode').setAttribute('aria-pressed',mode==='simulation');$('payment-real-mode').setAttribute('aria-pressed',mode==='real');
    $('payment-mode-title').textContent=tr(mode==='simulation'?'Simulation inbox':'Your incoming bank messages');
    $('payment-mode-description').textContent=tr(mode==='simulation'?'Fictional payments for testing. These never enter your personal spending totals.':'Money credited to your account, with bank and SMS timestamps kept separate.');
    $('payment-reset-demo').classList.toggle('hidden',mode!=='simulation');
    const banks=[...new Set(data().filter(isIncoming).map(t=>t.bank))].sort();if(!banks.includes(filters.bank))filters.bank='all';
    $('payment-bank').innerHTML=`<option value="all">${tr('All banks')}</option>`+banks.map(b=>`<option value="${escape(b)}">${escape(b)}</option>`).join('');
    const currencies=[...new Set(['VND','KRW',...data().filter(isIncoming).map(t=>t.currency)])];
    $('payment-currency').innerHTML=currencies.map(c=>`<option value="${escape(c)}">${escape(c)}</option>`).join('');writeFilters();
    rows=filterPayments(data(),filters);const a=paymentAnalysis(rows);
    $('payment-total').textContent=money(a.total,filters.currency);$('payment-count').textContent=tr('{count} incoming payments · {currency}',{count:a.count,currency:filters.currency});
    $('payment-peak').textContent=a.busiest.hour==null?'—':`${String(a.busiest.hour).padStart(2,'0')}:00`;
    $('payment-peak-note').textContent=a.busiest.count?tr('{count} payments in this hour',{count:a.busiest.count})+(a.hours.filter(h=>h.count===a.busiest.count).length>1?' · '+tr('tied peak'):''):tr('No timed payments');
    $('payment-precise').textContent=a.precise;$('payment-unknown').textContent=tr(filters.basis==='received'?'{count} without SMS arrival time':'{count} without bank time',{count:a.unknown});
    $('payment-chart-description').textContent=`${tr(filters.basis==='received'?'SMS arrival time':'Bank transaction time')} · ${tr(filters.zone==='Asia/Seoul'?'Korea · UTC+09':'Vietnam · UTC+07')}`;
    const max=Math.max(...a.hours.map(h=>h.count),1);
    $('payment-hours').innerHTML=a.hours.map(h=>`<button class="hour-column ${h.count===max?'hour-peak':''}" data-hour="${h.hour}" aria-label="${tr('Filter {hour}:00 hour, {count} payments',{hour:String(h.hour).padStart(2,'0'),count:h.count})}" title="${String(h.hour).padStart(2,'0')}:00 · ${tr('{count} payments',{count:h.count})} · ${escape(money(h.amount,filters.currency))}"><span class="hour-count">${h.count||''}</span><span class="hour-track"><span style="height:${h.count?Math.max(8,h.count/max*100):2}%"></span></span><span class="hour-label">${String(h.hour).padStart(2,'0')}</span></button>`).join('');
    const intervals={Night:'00–06',Morning:'06–12',Afternoon:'12–18',Evening:'18–24',Unknown:'No clock'};
    $('payment-periods').innerHTML=Object.entries(a.periods).map(([name,count])=>`<button data-period="${name}" class="period-chip ${filters.period===name?'selected':''}"><span>${tr(name)} <small>${tr(intervals[name])}</small></span><strong>${count}</strong></button>`).join('');
    $('payment-rows').innerHTML=rows.map(r=>{const t=r.transaction;return `<tr><td><div class="payment-person"><span class="payer-avatar">${escape((t.payer||t.merchant||'?').slice(0,1))}</span><div><strong>${escape(t.payer||t.merchant||tr('Unknown payer'))}</strong><small>${escape(t.paymentMemo||t.reference||tr('No memo supplied'))}</small></div></div></td><td><time class="payment-clock">${escape(r.parts?.time||tr('Time unavailable'))}</time><small>${r.date} · ${tr(r.period)}</small><small class="precision-tag">${tr(precisionLabel(r.instant))}</small></td><td>${escape(t.bank)}<small>${escape(t.account||tr('Account not supplied'))}</small></td><td><span class="tag">${escape(tr(t.paymentChannel||'Unclassified'))}</span></td><td class="align-right amount income">+${escape(money(t.amount,t.currency))}</td><td><button class="text-button" data-payment-detail="${escape(t.id)}" aria-label="${escape(tr('View payment from {name}',{name:t.payer||t.merchant}))}">${tr('Details')}</button></td></tr>`;}).join('');
    $('payment-empty').classList.toggle('hidden',rows.length>0);$('payment-export').disabled=!rows.length;
  }
  function reset(){Object.assign(filters,{bank:'all',month:localDate().slice(0,7),day:'',period:'all',channel:'all',query:'',from:'',to:'',sort:'newest'});writeFilters();render();}
  $('payment-filters').onsubmit=e=>e.preventDefault();
  for(const key of Object.keys(filters)){const el=$(`payment-${key}`);if(!el)continue;el.addEventListener(key==='query'?'input':'change',()=>{filters[key]=el.value;if(key==='currency'){filters.zone=paymentZone(el.value);filters.bank='all';}if(key==='day'&&el.value)filters.month=el.value.slice(0,7);if(key==='month')filters.day='';render();});}
  $('payment-clear-filters').onclick=reset;
  $('payment-demo-mode').onclick=()=>{mode='simulation';reset();};$('payment-real-mode').onclick=()=>{mode='real';reset();};
  $('payment-reset-demo').onclick=()=>{demoDay();mode='simulation';reset();toast('Loaded a fictional sample day.');};
  $('payment-import').onclick=()=>{getState().currency=filters.currency;$('import-button').click();};
  $('payment-periods').onclick=e=>{const button=e.target.closest('[data-period]');if(button){filters.period=filters.period===button.dataset.period?'all':button.dataset.period;filters.from='';filters.to='';render();}};
  $('payment-hours').onclick=e=>{const button=e.target.closest('[data-hour]');if(button){const hour=String(button.dataset.hour).padStart(2,'0');filters.from=hour+':00:00.000';filters.to=hour+':59:59.999';filters.period='all';render();}};
  function getSim(){return simulationMessage({payer:$('sim-payer').value,amount:Number($('sim-amount').value),currency:$('sim-currency').value,date:$('sim-date').value,time:$('sim-time').value,reference:$('sim-reference').value,memo:$('sim-memo').value,delayMs:Number($('sim-delay').value)});}
  function preview(){try{const message=getSim();const t=parseSms(message,{currency:$('sim-currency').value,date:$('sim-date').value}).transaction;$('sim-sms-preview').textContent=message.body+`\n\n${tr('SMS arrival: {time}',{time:timeParts(t.receivedTime,t.timeZone).date+' '+timeParts(t.receivedTime,t.timeZone).time+' ('+t.timeZone+')'})}`;$('sim-error').textContent='';}catch(e){$('sim-error').textContent=messageError(e.message);}}
  $('simulate-payment').onclick=()=>{$('sim-date').value=filters.day||localDate();$('sim-currency').value=['KRW','VND'].includes(filters.currency)?filters.currency:'VND';$('sim-reference').value='SIM-'+Date.now();$('sim-zone-note').textContent=tr($('sim-currency').value==='KRW'?'Bank clock uses Korea time (UTC+09).':'Bank clock uses Vietnam time (UTC+07).');preview();sim.showModal();};
  $('sim-preview').onclick=preview;$('sim-currency').onchange=()=>{$('sim-zone-note').textContent=tr($('sim-currency').value==='KRW'?'Bank clock uses Korea time (UTC+09).':'Bank clock uses Vietnam time (UTC+07).');preview();};
  $('payment-sim-close').onclick=()=>sim.close();
  $('payment-sim-form').onsubmit=e=>{e.preventDefault();try{const message=getSim();const result=parseSms(message,{currency:$('sim-currency').value,date:$('sim-date').value});if(result.status!=='parsed'||!isIncoming(result.transaction))throw new Error('This message was not recognized as an incoming payment.');if(demo.some(t=>t.fingerprint===result.transaction.fingerprint))throw new Error('This reference was already delivered. Use a new reference for a separate payment.');demo.push({...result.transaction,id:crypto.randomUUID(),simulation:true});mode='simulation';Object.assign(filters,{currency:result.transaction.currency,month:result.transaction.date.slice(0,7),day:result.transaction.date,zone:result.transaction.timeZone,bank:'all',from:'',to:'',period:'all',query:'',channel:'all'});sim.close();render();toast('Simulated SMS received. No real funds or records changed.');}catch(error){$('sim-error').textContent=messageError(error.message);}};
  $('payment-rows').onclick=e=>{const button=e.target.closest('[data-payment-detail]');if(!button)return;const t=data().find(t=>t.id===button.dataset.paymentDetail);$('payment-detail-id').value=t.id;for(const f of ['payer','account'])$('payment-detail-'+f).value=t[f]||'';$('payment-detail-channel').value=t.paymentChannel||'Unclassified';$('payment-detail-memo').value=t.paymentMemo||'';$('payment-detail-kind').value=t.ownAccount?'own':'external';$('payment-detail-raw').textContent=t.raw;
    const description=(instant)=>{const p=timeParts(instant,filters.zone);return p?`${p.date} ${p.time} · ${tr(precisionLabel(instant))}`:tr('Not provided');};
    $('payment-detail-summary').innerHTML=`<div class="payment-detail-total">${escape(money(t.amount,t.currency))}<small>${tr(mode==='simulation'?'Simulated payment':'Imported bank message')} · ${escape(t.bank)}</small></div><dl class="payment-timestamps"><dt>${tr('Bank transaction')}</dt><dd>${escape(description(t.transactionTime))}</dd><dt>${tr('SMS arrived')}</dt><dd>${escape(description(t.receivedTime))}</dd><dt>${tr('Display zone')}</dt><dd>${escape(filters.zone)}</dd><dt>${tr('Reference')}</dt><dd>${escape(t.reference||tr('Not provided'))}</dd></dl><p class="helper">${tr('An SMS timestamp records message arrival, not the bank’s settlement time.')}${t.transactionTime?.assumedZone?' '+tr('Bank time zone assumed from the bank/currency; no zone was in the message.'):''}</p>`;detail.showModal();};
  $('payment-detail-close').onclick=()=>detail.close();
  $('payment-detail-form').onsubmit=async e=>{e.preventDefault();const t=data().find(t=>t.id===$('payment-detail-id').value);if(!t)return;t.payer=$('payment-detail-payer').value.trim();t.paymentChannel=$('payment-detail-channel').value;t.account=$('payment-detail-account').value.trim();t.paymentMemo=$('payment-detail-memo').value.trim();t.ownAccount=$('payment-detail-kind').value==='own';if(t.ownAccount){t.type='transfer';t.category='Transfer';}if(mode==='real')await changed();detail.close();render();toast(t.ownAccount?'Own-account transfer excluded from money received.':'Payment classification saved.');};
  $('payment-export').onclick=()=>{const fields=['payer','amount','currency','bank','account','reference','channel','memo','date','time','zone','time_basis','precision','bank_epoch_ms','sms_received_epoch_ms','simulation'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+fields.join(',')+'\r\n'+rows.map(r=>{const t=r.transaction;return [t.payer||t.merchant,t.amount,t.currency,t.bank,t.account,t.reference,t.paymentChannel,t.paymentMemo,r.date,r.parts?.time||'',filters.zone,filters.basis,precisionLabel(r.instant),t.transactionTime?.epochMs??'',t.receivedTime?.epochMs??'',mode==='simulation'].map(cell).join(',');}).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`penny-incoming-${mode}-${filters.currency}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  writeFilters();
  return {render,afterImport(){mode='real';filters.currency=getState().currency;filters.zone=paymentZone(filters.currency);filters.month=getState().month;filters.day='';filters.bank='all';filters.from='';filters.to='';filters.period='all';filters.channel='all';filters.query='';render();}};
}
